#include <stdio.h>

typedef struct {
    int id;
    int salary;
} Emp;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    Emp arr[1000];
    for (int i = 0; i < n; i++) {
        if (scanf("%d %d", &arr[i].id, &arr[i].salary) != 2) {
            return 1;
        }
    }
    int q;
    if (scanf("%d", &q) != 1) {
        return 1;
    }
    FILE *fp = fopen("/tmp/atom_day20_emp.bin", "wb");
    if (fp == NULL) {
        printf("OPEN_FAIL\n");
        return 0;
    }
    fwrite(arr, sizeof(Emp), n, fp);
    fclose(fp);
    fp = fopen("/tmp/atom_day20_emp.bin", "rb");
    if (fp == NULL) {
        printf("OPEN_FAIL\n");
        return 0;
    }
    int found = 0;
    int salary = 0;
    for (int i = 0; i < n; i++) {
        if (fseek(fp, (long)i * (long)sizeof(Emp), SEEK_SET) != 0) {
            break;
        }
        Emp e;
        if (fread(&e, sizeof(Emp), 1, fp) != 1) {
            break;
        }
        if (e.id == q) {
            found = 1;
            salary = e.salary;
            break;
        }
    }
    fclose(fp);
    if (found) {
        printf("SALARY %d\n", salary);
    } else {
        printf("NOT_FOUND\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, c;
    if (scanf("%d %d", &n, &c) != 2) {
        return 1;
    }
    if (c == 0) {
        FILE *fp = fopen("/tmp/atom_day20_no_such_file.txt", "r");
        if (fp == NULL) {
            printf("OPEN_FAILED\n");
            return 0;
        }
        fclose(fp);
        printf("UNEXPECTED\n");
        return 0;
    } else {
        FILE *fp = fopen("/tmp/atom_day20_resilient.txt", "w");
        if (fp == NULL) {
            printf("OPEN_FAILED\n");
            return 0;
        }
        fprintf(fp, "%d\n", n);
        fclose(fp);
        fp = fopen("/tmp/atom_day20_resilient.txt", "r");
        if (fp == NULL) {
            printf("OPEN_FAILED\n");
            return 0;
        }
        int parsed = 0;
        int sign = 1;
        int started = 0;
        int ch;
        while ((ch = fgetc(fp)) != EOF) {
            if (ch == '-') {
                sign = -1;
            } else if (ch >= '0' && ch <= '9') {
                parsed = parsed * 10 + (ch - '0');
                started = 1;
            } else if (started) {
                break;
            }
        }
        parsed = sign * parsed;
        fclose(fp);
        printf("FINAL %d\n", parsed);
        return 0;
    }
}
